using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Diagnostics;using System.Web.Script.Serialization;
public class PairFixture {
 static string dir,op="",mode="basic",applied="";static Form main,alpha;static TextBox result,draft,other;static CheckBox enabled;static ComboBox format;static Panel scroll;static bool entering,lastClicked;static int lhs,n,toggles;static List<string> buttons=new List<string>(),actions=new List<string>();static JavaScriptSerializer json=new JavaScriptSerializer();
 static void Save(){var p=Path.Combine(dir,"state.json");var temp=p+".tmp";File.WriteAllText(temp,json.Serialize(new{display=result.Text,draft=draft.Text,Alpha=other.Text,enabled=enabled.Checked,toggle_count=toggles,mode=mode,format=(string)format.SelectedItem,applied=applied,scrolled=scroll.AutoScrollPosition.Y < -100,scroll_y=-scroll.AutoScrollPosition.Y,last_record_clicked=lastClicked,buttons=buttons,actions=actions,pid=Process.GetCurrentProcess().Id,window=main.Handle.ToInt64(),alpha_window=alpha.Handle.ToInt64(),screen=new[]{SystemInformation.VirtualScreen.Width,SystemInformation.VirtualScreen.Height,1}}));try{if(File.Exists(p))File.Replace(temp,p,null);else File.Move(temp,p);}catch(IOException){}}
 static void Calc(string key){buttons.Add(key);int d;if(int.TryParse(key,out d)){n=entering?n*10+d:d;entering=true;result.Text=n.ToString();}else if(key=="×"){lhs=n;op=key;entering=false;result.Text=lhs+" ×";}else if(key=="="){n=op=="×"?lhs*n:n;entering=false;result.Text=n.ToString();}else{n=0;lhs=0;op="";entering=false;result.Text="0";}Save();}
 [STAThread]public static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);Application.EnableVisualStyles();main=new Form{Text="Paired task fixture",ClientSize=new Size(640,680),StartPosition=FormStartPosition.Manual,Location=new Point(20,20)};alpha=new Form{Text="Alpha document",ClientSize=new Size(260,200),StartPosition=FormStartPosition.Manual,Location=new Point(710,50)};result=new TextBox{Text="0",AccessibleName="Result",Name="result",Bounds=new Rectangle(20,20,580,35)};draft=new TextBox{Text="seed",AccessibleName="Draft",Name="draft",Multiline=true,Bounds=new Rectangle(20,140,580,75)};other=new TextBox{Text="alpha",AccessibleName="Alpha",Name="alpha",Bounds=new Rectangle(20,50,210,30)};main.Controls.Add(result);main.Controls.Add(draft);alpha.Controls.Add(other);
 int i=0;foreach(string label in new[]{"6","7","×","=","Clear"}){string key=label;var b=new Button{Text=key,AccessibleName=key,Name="button-"+key,Bounds=new Rectangle(20+i++*110,80,100,35)};b.Click+=(o,e)=>Calc(key);main.Controls.Add(b);}
 enabled=new CheckBox{Text="Enable option",Name="enabled",AccessibleName="Enable option",Bounds=new Rectangle(20,240,140,25)};enabled.CheckedChanged+=(o,e)=>{toggles++;actions.Add("toggle");Save();};main.Controls.Add(enabled);
 var basic=new RadioButton{Text="Basic mode",Name="basic",AccessibleName="Basic mode",Bounds=new Rectangle(175,235,150,25),Checked=true};var detail=new RadioButton{Text="Detailed mode",Name="detailed",AccessibleName="Detailed mode",Bounds=new Rectangle(175,265,150,25)};basic.CheckedChanged+=(o,e)=>{if(basic.Checked){mode="basic";actions.Add("mode:basic");Save();}};detail.CheckedChanged+=(o,e)=>{if(detail.Checked){mode="detailed";actions.Add("mode:detailed");Save();}};main.Controls.Add(basic);main.Controls.Add(detail);
 format=new ComboBox{AccessibleName="Format",Name="format",DropDownStyle=ComboBoxStyle.DropDownList,Bounds=new Rectangle(350,240,180,30)};format.Items.AddRange(new object[]{"Plain","Markdown","CSV"});format.SelectedIndex=0;format.SelectedIndexChanged+=(o,e)=>{actions.Add("format:"+format.SelectedItem);Save();};main.Controls.Add(format);
 scroll=new Panel{Name="records",AccessibleName="Records",AutoScroll=true,Bounds=new Rectangle(20,310,580,290)};for(i=0;i<16;i++){var b=new Button{Text=i==15?"Last record":"Record "+(i+1),AccessibleName=i==15?"Last record":"Record "+(i+1),Name=i==15?"last-record":"record-"+i,Bounds=new Rectangle(15,i*55+8,300,35)};if(i==15)b.Click+=(o,e)=>{lastClicked=true;actions.Add("last_record");Save();};scroll.Controls.Add(b);}main.Controls.Add(scroll);
 var apply=new Button{Text="Apply draft",Name="apply",AccessibleName="Apply draft",Bounds=new Rectangle(20,625,150,35)};apply.Click+=(o,e)=>{applied=draft.Text;actions.Add("apply");Save();};main.Controls.Add(apply);
 var timer=new Timer{Interval=50};timer.Tick+=(o,e)=>Save();main.Shown+=(o,e)=>{alpha.Show();main.Activate();Save();timer.Start();};Application.Run(main);}
}
